    private static JSONObject readProcessCheckpoint(File file)throws Exception {
        if(!file.isFile()||java.nio.file.Files.isSymbolicLink(file.toPath())||file.length()>2*1024*1024)throw new AssertionError("QA_UI_PROCESS_CHECKPOINT_MISSING");
        return new JSONObject(new String(java.nio.file.Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8));
    }
    private static void writeProcessCheckpoint(File file,JSONObject value)throws Exception {
        android.util.AtomicFile target=new android.util.AtomicFile(file);FileOutputStream output=null;try{output=target.startWrite();output.write(value.toString().getBytes(StandardCharsets.UTF_8));target.finishWrite(output);output=null;}catch(Exception failure){if(output!=null)target.failWrite(output);throw failure;}
    }
    private static void finishProcessActivity(PixelMcpInstrumentation test,Session session,Activity activity)throws Exception {
        if(activity==null)return;test.runOnMainSync(activity::finish);test.waitForIdleSync();if(!session.destroyed.await(15,TimeUnit.SECONDS))throw new AssertionError("QA_UI_PROCESS_ACTIVITY_NOT_DESTROYED");
        settleActivityWork(test);
    }

    /** Drain worker -> UI callback -> worker handoffs before deleting this QA scope. */
    private static void settleActivityWork(PixelMcpInstrumentation test)throws Exception {
        if(Looper.myLooper()==Looper.getMainLooper())throw new AssertionError("QA_UI_WORKER_BARRIER_ON_MAIN");
        Field field=MainActivity.class.getDeclaredField("BACKUP_CHECKPOINTS");field.setAccessible(true);ExecutorService executor=(ExecutorService)field.get(null);
        executor.submit(()->{}).get(30,TimeUnit.SECONDS);test.waitForIdleSync();executor.submit(()->{}).get(30,TimeUnit.SECONDS);
    }

