    private static JSONObject nativeFormSessions(OwnerNativeAcceptance.Fixture fixture)throws Exception {
        JSONObject state=new BrowserDraftRepository(fixture.context,fixture.store).read(new JSONObject().put("formatVersion",1).put("action","get").put("key",FORM_SESSIONS_KEY).toString());
        if(state.getBoolean("review_required")||!state.getBoolean("initialized")||!state.getBoolean("present"))throw new AssertionError("QA_UI_PROCESS_NATIVE_DRAFTS_MISSING");
        JSONObject value=new JSONObject(state.getString("value"));if(value.getInt("formatVersion")!=1||value.optJSONObject("entries")==null)throw new AssertionError("QA_UI_PROCESS_NATIVE_DRAFTS_INVALID");return value;
    }
    private static JSONObject processEditByKind(PixelMcpInstrumentation test,WebView view,String kind)throws Exception {
        return processJson(test,view,"(()=>{const edits=HGFormDrafts.list("+JSONObject.quote(kind)+");if(edits.length!==1)throw Error('QA_UI_PROCESS_ONE_DRAFT_REQUIRED');return edits[0];})()");
    }
    private static void resumeProcessEdit(PixelMcpInstrumentation test,WebView view,String kind,String session)throws Exception {
        if(kind.equals("inquiry")){action(test,view,"BUSINESS_INQUIRY_LIST","openPage('revier-inquiries')");click(test,view,"#revier-inquiries [data-revier-restore-draft='"+session+"']");}
        else if(kind.equals("order"))action(test,view,"BUSINESS_ORDER_RESUME","const edit=HGFormDrafts.list('order').find(row=>row.session_id==="+JSONObject.quote(session)+");if(!edit)throw Error('QA_UI_PROCESS_ORDER_DRAFT_MISSING');window.resumeOrderEdit(edit)");
        else if(kind.equals("offer")){action(test,view,"BUSINESS_OFFER_LIST","openPage('offers-page');OfferUI.refresh()");click(test,view,"[data-offer-resume='"+session+"']");}
        else throw new AssertionError("QA_UI_PROCESS_KIND_UNSUPPORTED");
    }
    private static void assertPendingBusiness(PixelMcpInstrumentation test,OwnerNativeAcceptance.Fixture fixture,JSONObject drafts,JSONObject expected)throws Exception {
        JSONObject entries=drafts.getJSONObject("entries");test.yes(entries.length()==4);
        for(String kind:new String[]{"inquiry","order","offer"}){
            JSONObject original=expected.getJSONObject("edits").getJSONObject(kind),edit=entries.getJSONObject(original.getString("session_id")),action=expected.getJSONObject("actions").getJSONObject(kind),pending=edit.getJSONObject("pending");
            test.yes(edit.getString("kind").equals(kind)&&pending.getString("tool").equals(action.getString("tool"))&&PixelMcpWriteTools.hash(pending.getJSONObject("args")).equals(PixelMcpWriteTools.hash(action.getJSONObject("args"))));
            if(kind.equals("inquiry"))test.yes(pending.getJSONObject("args").getString("request_id").equals(original.getString("request_id")));
            for(String field:new String[]{"baseline","values","context"})test.yes(PixelMcpWriteTools.hash(edit.get(field)).equals(PixelMcpWriteTools.hash(original.get(field))));
            JSONObject proof=fixture.call("inspect_edit_action",new JSONObject().put("original_tool",pending.getString("tool")).put("original_args",pending.getJSONObject("args")));test.yes(proof.getString("state").equals("confirmed")&&!proof.getBoolean("business_write_performed")&&proof.getString("entity_id").equals(action.getString("entity_id")));
        }
        JSONObject independent=expected.getJSONObject("independent");test.yes(PixelMcpWriteTools.hash(entries.getJSONObject(independent.getString("session_id"))).equals(PixelMcpWriteTools.hash(independent)));
    }

