    private static JSONObject oneTool(OwnerNativeAcceptance.Fixture f,String tool)throws Exception {JSONArray rows=f.call(tool,new JSONObject()).getJSONArray("items");if(rows.length()!=1)throw new AssertionError("QA_UI_ONE_"+tool.toUpperCase(Locale.ROOT));return rows.getJSONObject(0);}
    private static String qaImage()throws Exception {Bitmap bitmap=Bitmap.createBitmap(32,24,Bitmap.Config.ARGB_8888);try{bitmap.eraseColor(0xff6d913b);ByteArrayOutputStream bytes=new ByteArrayOutputStream();if(!bitmap.compress(Bitmap.CompressFormat.PNG,100,bytes))throw new IOException("QA_BITMAP_ENCODE_FAILED");return android.util.Base64.encodeToString(bytes.toByteArray(),android.util.Base64.NO_WRAP);}finally{bitmap.recycle();}}
    /** Same APK collector, native media acknowledgements and sanitizer used by MainActivity.
     * The isolated HTTPS origin deliberately cannot invoke Main's file-origin checkpoint queue.
     * Its real repository save/readback below is the acknowledgement boundary; no descriptor is invented.
     */
    private static JSONObject careBrowserCheckpoint(PixelMcpInstrumentation test,WebView view,Session session)throws Exception {
        String businessBefore=LocalAuthorityMigration.businessHash(session.fixture.store.getState()),collector;
        try(InputStream input=session.fixture.context.getAssets().open("backup-browser-state.js");ByteArrayOutputStream output=new ByteArrayOutputStream()){
            byte[] block=new byte[8192];int count;while((count=input.read(block))!=-1)output.write(block,0,count);collector=new String(output.toByteArray(),StandardCharsets.UTF_8);
        }
        action(test,view,"CARE_BACKUP_COLLECTOR_MEDIA",collector+";window.HGBackupSnapshot.bind("+JSONObject.quote(session.token)+",false);window.qaCareBrowserCapture=null;window.qaCareBrowserCaptureFailed=false;window.HGBackupSnapshot.prepareMedia(false).then(()=>{window.qaCareBrowserCapture=JSON.stringify(window.HGBackupSnapshot.capture());}).catch(()=>{window.qaCareBrowserCaptureFailed=true;});");
        expect(test,view,"CARE_BACKUP_MEDIA_ACK","typeof window.qaCareBrowserCapture==='string'||window.qaCareBrowserCaptureFailed");
        if("true".equals(js(test,view,"window.qaCareBrowserCaptureFailed")))throw new AssertionError("QA_CARE_BACKUP_COLLECTOR_FAILED");
        JSONObject raw=processJson(test,view,"JSON.parse(window.qaCareBrowserCapture)"),checkpoint=raw.getJSONObject("_checkpoint");
        test.yes(checkpoint.getString("pageToken").equals(session.token)&&checkpoint.getLong("sequence")>0);
        raw.remove("_checkpoint");JSONObject browser=MainActivity.sanitizeBackupCheckpoint(raw),descriptor=browser.getJSONObject("editor_state"),nativeState=new BrowserDraftRepository(session.fixture.context,session.fixture.store).read(new JSONObject().put("formatVersion",1).put("action","list").toString());
        test.yes(nativeState.getJSONArray("states").length()>0&&!descriptor.getBoolean("review_required")&&descriptor.getString("record_hash").equals(nativeState.getString("record_hash"))&&PixelMcpWriteTools.hash(descriptor.getJSONObject("context")).equals(PixelMcpWriteTools.hash(nativeState.getJSONObject("context"))));
        JSONObject media=new BrowserMediaRepository(session.fixture.context,session.fixture.store).status();test.yes(media.getBoolean("mirror_complete")&&media.getString("mode").equals("ACTIVE")&&media.getInt("pending_write_count")==0);
        test.yes(businessBefore.equals(LocalAuthorityMigration.businessHash(session.fixture.store.getState())));
        expect(test,view,"CARE_BACKUP_COLLECTOR_REAL_NATIVE","qaBusinessMethodCount===38&&qaBusinessCalls.includes('getBrowserDraftState')&&qaRuntimeErrors===0&&qaPlatformBlocked===0");
        trace(test,"CARE_PRODUCTION_COLLECTOR_NATIVE_EDITOR_DIGEST_MEDIA_ACK_PASS");return browser;
    }
