                File original=new File(data,"files/customer-photo-originals/"+attachment.getString("storage_name"));test.yes(original.isFile()&&EncryptedBackupArchive.sha256(original).equals(attachment.getString("content_sha256"))&&staged.manifest.getString("backupId").equals(id));
